Codi de solució HTML<pre><code>&lt;!DOCTYPE html&gt;
&lt;html lang="ca"&gt;
&lt;head&gt;
&lt;meta charset="UTF-8"&gt;
&lt;meta name="viewport" content="width=device-width, initial-scale=1.0"&gt;
&lt;title&gt;Formulari Accessible&lt;/title&gt;
&lt;style&gt;
    .checkbox, .radiobutton {
    display: inline-block;
    padding: 10px 20px;
    margin: 5px;
    border: 1px solid #333;
    border-radius: 4px;
    cursor: pointer;
    }
    .checkbox[aria-checked="true"], .radiobutton[aria-checked="true"] {
    background-color: #4caf50;
    color: white;
    }
    .checkbox:focus, .radiobutton:focus, input:focus {
    outline: 2px solid #0078d4;
    }
&lt;/style&gt;
&lt;/head&gt;
&lt;body&gt;
&lt;h1&gt;Formulari Accessible&lt;/h1&gt;
&lt;form aria-labelledby="form-title"&gt;
    &lt;h2 id="form-title"&gt;Formulari d'exemple&lt;/h2&gt;

    &lt;!-- Camp de text --&gt;
    &lt;div class="form-group"&gt;
    &lt;label for="nom"&gt;Nom:&lt;/label&gt;
    &lt;input type="text" id="nom" name="nom" aria-required="true" aria-describedby="nom-help"&gt;
    &lt;div id="nom-help" class="help-text"&gt;Introdueix el teu nom complet.&lt;/div&gt;
    &lt;/div&gt;

    &lt;!-- Caselles de verificació --&gt;
    &lt;div class="form-group"&gt;
    &lt;p&gt;Quins serveis t'interessen?&lt;/p&gt;
    &lt;div role="checkbox" tabindex="0" aria-checked="false" class="checkbox"&gt;Disseny web&lt;/div&gt;
    &lt;div role="checkbox" tabindex="0" aria-checked="false" class="checkbox"&gt;Màrqueting&lt;/div&gt;
    &lt;div role="checkbox" tabindex="0" aria-checked="false" class="checkbox"&gt;SEO&lt;/div&gt;
    &lt;/div&gt;

    &lt;!-- Radiobuttons --&gt;
    &lt;div class="form-group"&gt;
    &lt;p&gt;Selecciona el teu pla preferit:&lt;/p&gt;
    &lt;div role="radio" tabindex="0" aria-checked="false" class="radiobutton"&gt;Bàsic&lt;/div&gt;
    &lt;div role="radio" tabindex="0" aria-checked="false" class="radiobutton"&gt;Avançat&lt;/div&gt;
    &lt;div role="radio" tabindex="0" aria-checked="false" class="radiobutton"&gt;Premium&lt;/div&gt;
    &lt;/div&gt;

    &lt;!-- Botó d'enviament --&gt;
    &lt;div class="form-group"&gt;
    &lt;button type="submit" aria-label="Enviar formulari"&gt;Enviar&lt;/button&gt;
    &lt;/div&gt;
&lt;/form&gt;

&lt;script&gt;
    // Configuració per a caselles de verificació
    const checkboxes = document.querySelectorAll('.checkbox');
    checkboxes.forEach(checkbox =&gt; {
    checkbox.addEventListener('click', () =&gt; {
        const isChecked = checkbox.getAttribute('aria-checked') === 'true';
        checkbox.setAttribute('aria-checked', !isChecked);
    });

    checkbox.addEventListener('keydown', (event) =&gt; {
        if (event.key === ' ' || event.key === 'Enter') {
        event.preventDefault();
        const isChecked = checkbox.getAttribute('aria-checked') === 'true';
        checkbox.setAttribute('aria-checked', !isChecked);
        }
    });
    });

    // Configuració per a botons de ràdio
    const radiobuttons = document.querySelectorAll('.radiobutton');
    radiobuttons.forEach(radio =&gt; {
    radio.addEventListener('click', () =&gt; {
        radiobuttons.forEach(rb =&gt; rb.setAttribute('aria-checked', 'false'));
        radio.setAttribute('aria-checked', 'true');
    });

    radio.addEventListener('keydown', (event) =&gt; {
        if (event.key === ' ' || event.key === 'Enter') {
        event.preventDefault();
        radiobuttons.forEach(rb =&gt; rb.setAttribute('aria-checked', 'false'));
        radio.setAttribute('aria-checked', 'true');
        }
    });
    });
&lt;/script&gt;
&lt;/body&gt;
&lt;/html&gt;
</code></pre>

